async function anonymous($fn,$gc,$now,$heap,$params,$counters
) {




    let _ = 0; let t = 0;
    let samples = new Array(2 ** 20);
    const heap = { _: 0, total: 0, min: Infinity, max: -Infinity };
    const gc = { total: 0, min: Infinity, max: -Infinity };



    $gc();

    for (; _ < 1000000000; _++) {
      if (_ >= 12 && t >= 1412400000) break;




        igc: {
          const t0 = $now();
          $gc(); t += $now() - t0;
        }



      const h0 = $heap();
       const t0 = $now();



          $fn();



      const t1 = $now();



        heap: {
          const t0 = $now();
          const h1 = ($heap() - h0) ; t += $now() - t0;

          if (0 <= h1) {
            heap._++;
            heap.total += h1;
            heap.min = Math.min(h1, heap.min);
            heap.max = Math.max(h1, heap.max);
          }
        }



        igc: {
          const t0 = $now();
          $gc(); const t1 = $now() - t0;

          t += t1;
          gc.total += t1;
          gc.min = Math.min(t1, gc.min);
          gc.max = Math.max(t1, gc.max);
        }
      ;

      const diff = t1 - t0;
      t += t1 - t0;
      samples[_] = diff ;
    }

    samples.length = _;
    samples.sort((a, b) => a - b);
    if (samples.length > 12) samples = samples.slice(2, -2);

    return {
      samples,
      min: samples[0],
      max: samples[samples.length - 1],
      p25: samples[(.25 * (samples.length - 1)) | 0],
      p50: samples[(.50 * (samples.length - 1)) | 0],
      p75: samples[(.75 * (samples.length - 1)) | 0],
      p99: samples[(.99 * (samples.length - 1)) | 0],
      p999: samples[(.999 * (samples.length - 1)) | 0],
      avg: samples.reduce((a, v) => a + v, 0) / samples.length,
      ticks: samples.length ,
      heap: { ...heap, avg: heap.total / heap._ },
      gc: { ...gc, avg: gc.total / _ },

    };



}

